// 🔒 BUILD CLAIM SQL — reclama eventos del inbox con un token único + lease.
// Un evento sólo lo procesa quien tiene su claim_token. Si esta ejecución se
// cae a mitad de camino, el lease vence (10 min) y otro ciclo lo retoma; la
// idempotencia contra el CRM (providerCallId / "Ref:") evita duplicados.
// Nunca se reclama un evento de un lead que ya tiene otro evento en proceso.
// Todas las horas en UTC explícito (UTC_TIMESTAMP).
// ============================================================================
const BATCH = 100;
const LEASE_MIN = 10;
let execId = '';
try { execId = String($execution.id || ''); } catch (e) { execId = ''; }
const token = ('wf9-' + execId + '-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10)).slice(0, 64);
const T = "'" + token.replace(/[^A-Za-z0-9_-]/g, '') + "'";
const MS = c => 'IF(' + c + ' IS NULL, NULL, TIMESTAMPDIFF(MICROSECOND, \'1970-01-01 00:00:00\', ' + c + ') DIV 1000)';

const claim_sql = [
  'UPDATE wf_call_events SET state = \'PROCESSING\', claim_token = ' + T + ',',
  'lease_until = UTC_TIMESTAMP(3) + INTERVAL ' + LEASE_MIN + ' MINUTE, process_attempts = process_attempts + 1',
  'WHERE ((state IN (\'RECEIVED\', \'FAILED\') AND next_attempt_at <= UTC_TIMESTAMP(3))',
  'OR (state = \'PROCESSING\' AND lease_until < UTC_TIMESTAMP(3)))',
  'AND (lead_id IS NULL OR lead_id NOT IN (SELECT b.lead_id FROM (SELECT DISTINCT lead_id FROM wf_call_events',
  'WHERE state = \'PROCESSING\' AND lease_until >= UTC_TIMESTAMP(3) AND lead_id IS NOT NULL) b))',
  'ORDER BY next_attempt_at ASC, id ASC LIMIT ' + BATCH
].join(' ');

const read_sql = [
  'SELECT e.event_key, e.source, e.provider, e.external_id, e.lead_id, e.phone, e.call_attempts, e.crm_attempt,',
  'e.followup_id, e.lifecycle_applied, e.error_count, e.process_attempts, e.resolution AS prev_resolution, e.claim_token,',
  MS('e.event_at') + ' AS event_at_ms,',
  MS('e.dispatched_at') + ' AS dispatched_at_ms,',
  MS('e.first_seen_at') + ' AS first_seen_at_ms,',
  '(SELECT ' + MS('MAX(x.event_at)') + ' FROM wf_call_events x WHERE x.lead_id = e.lead_id AND x.lifecycle_applied = 1 AND x.event_key <> e.event_key) AS lead_latest_lifecycle_at_ms,',
  '(SELECT COUNT(*) FROM wf_call_events x WHERE x.lead_id = e.lead_id AND x.source = \'stringee\' AND x.state IN (\'RECEIVED\', \'PROCESSING\', \'FAILED\') AND x.event_key <> e.event_key) AS lead_unresolved_jobs,',
  '(SELECT COUNT(*) FROM wf_call_events x WHERE x.lead_id = e.lead_id AND x.event_key <> e.event_key AND e.dispatched_at IS NOT NULL AND x.dispatched_at IS NOT NULL AND x.dispatched_at > e.dispatched_at) AS lead_newer_dispatch,',
  '(SELECT GROUP_CONCAT(x.followup_id) FROM wf_call_events x WHERE x.lead_id = e.lead_id AND x.followup_id IS NOT NULL AND x.event_key <> e.event_key AND x.created_at > UTC_TIMESTAMP(3) - INTERVAL 14 DAY) AS lead_claimed_followups,',
  'CASE WHEN e.source = \'elevenlabs\' THEN (SELECT x.event_key FROM wf_call_events x WHERE x.source = \'stringee\' AND (x.conversation_id = e.external_id',
  'OR (e.provider = \'stringee\' AND e.lead_id IS NOT NULL AND x.lead_id = e.lead_id AND e.call_attempts IS NOT NULL AND x.call_attempts = e.call_attempts',
  'AND e.event_at IS NOT NULL AND ABS(TIMESTAMPDIFF(SECOND, COALESCE(x.event_at, x.dispatched_at, x.first_seen_at), e.event_at)) <= 1800)) LIMIT 1) ELSE NULL END AS linked_job_key',
  'FROM wf_call_events e WHERE e.claim_token = ' + T + ' AND e.state = \'PROCESSING\' ORDER BY e.lead_id, e.event_at, e.id'
].join(' ');

// Una sola query (UPDATE; SELECT) en un único nodo MySQL: no depende de referencias a otros
// nodos dentro de la query (en el nodo MySQL de n8n esas referencias se resuelven como undefined).
const claim_read_sql = claim_sql + '; ' + read_sql;
return [{ json: { claim_token: token, claim_sql, read_sql, claim_read_sql } }];

