// HTTP que nunca lanza: devuelve {ok,status,body}
async function http(method, url, opts = {}) {
  try {
    const r = await self.helpers.httpRequest({
      method,
      url,
      body: opts.body,
      json: true,
      headers: Object.assign({ 'Content-Type': 'application/json' }, opts.headers || {}),
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
      timeout: opts.timeout || 20000
    });
    return { ok: r.statusCode >= 200 && r.statusCode < 300, status: r.statusCode, body: r.body };
  } catch (e) {
    return { ok: false, status: 0, body: { error: String((e && e.message) || e) } };
  }
}

let TOKEN = null;
async function getToken(force) {
  if (TOKEN && !force) return TOKEN;
  const r = await http('POST', CFG.TOKEN_URL, {});
  const t = r.ok && r.body && r.body.accessToken;
  if (!t) throw new Error('token service falló HTTP ' + r.status);
  TOKEN = t;
  return t;
}
async function ls(method, path, body) {
  let t = await getToken(false);
  let r = await http(method, CFG.LS_BASE + path, { body, headers: { Authorization: 'Bearer ' + t } });
  if (r.status === 401) {
    t = await getToken(true);
    r = await http(method, CFG.LS_BASE + path, { body, headers: { Authorization: 'Bearer ' + t } });
  }
  return r;
}

// Literales SQL seguros (MariaDB con escapes de backslash activos).
// El nodo MySQL de n8n elimina los saltos de línea al separar sentencias,
// por eso aquí nunca se dejan saltos de línea crudos dentro de un literal.
function q(v) {
  if (v === null || v === undefined) return 'NULL';
  if (typeof v === 'number') return Number.isFinite(v) ? String(Math.trunc(v)) : 'NULL';
  const s = String(v)
    .replace(/\u0000/g, '')
    .replace(/[\r\n]+/g, ' ').replace(/\$/g, '')
    .replace(/\\/g, '\\\\')
    .replace(/'/g, "''")
    .replace(/\{\{/g, '{ {')
    .replace(/\}\}/g, '} }');
  return "'" + s + "'";
}
// DATETIME(3) en UTC explícito
function dt(msv) {
  if (!msv || !Number.isFinite(Number(msv))) return 'NULL';
  return "'" + new Date(Number(msv)).toISOString().replace('T', ' ').replace('Z', '') + "'";
}
function ms(v) {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number') return Number.isFinite(v) ? v : null;
  const t = new Date(v).getTime();
  return Number.isFinite(t) ? t : null;
}
function iso(msv) { return new Date(msv).toISOString(); }
function safeInt(v) { const n = Number(v); return Number.isFinite(n) && n >= 0 ? Math.trunc(n) : 0; }
function validAttempt(v) {
  const n = Number(v);
  return Number.isInteger(n) && n >= 1 && n <= 99 ? n : null;
}

// Mismo cálculo que WF2 (Classify Dial Result Asterisk): días hábiles saltan sábado y domingo
function addHours(d, h) { return new Date(d.getTime() + h * 3600000); }
function addBusinessDays(d, days) {
  const r = new Date(d.getTime());
  let added = 0;
  while (added < days) {
    r.setDate(r.getDate() + 1);
    const wd = r.getDay();
    if (wd !== 0 && wd !== 6) added++;
  }
  return r;
}

// Política 3x3. attempt = número real de intento (1..9). >=9 => agotado.
function planFor(attempt, baseMs) {
  const a = Math.max(1, Math.trunc(attempt));
  if (a >= CFG.MAX_ATTEMPTS) {
    return { exhausted: true, text: 'Maximum of 9 call attempts reached. Lead closed as unresponsive.' };
  }
  const pos = ((a - 1) % 3) + 1;
  const cycle = Math.ceil(a / 3);
  const base = new Date(baseMs);
  let at, text;
  if (pos === 1) { at = addHours(base, 2); text = 'Next attempt in 2 hours.'; }
  else if (pos === 2) { at = addHours(base, 3); text = 'Next attempt in 3 hours.'; }
  else if (cycle === 1) { at = addBusinessDays(base, 2); text = 'End of cycle 1. Next cycle in 2 business days.'; }
  else { at = addBusinessDays(base, 3); text = 'End of cycle 2. Next cycle in 3 business days.'; }
  return { exhausted: false, atMs: at.getTime(), text, cycle, pos };
}
function attemptText(a) {
  if (a <= CFG.MAX_ATTEMPTS) {
    const pos = ((a - 1) % 3) + 1;
    const cycle = Math.ceil(a / 3);
    return 'Call attempt ' + a + ' of 9 (cycle ' + cycle + ', ' + pos + '/3).';
  }
  return 'Call attempt ' + a + ', beyond the configured maximum of 9.';
}

function unwrapLead(body) {
  if (!body || typeof body !== 'object') return null;
  if (body.lead && typeof body.lead === 'object') return body.lead;
  return body.id ? body : null;
}
function listFollowups(body) {
  if (Array.isArray(body)) return body;
  if (body && Array.isArray(body.followUps)) return body.followUps;
  if (body && Array.isArray(body.followups)) return body.followups;
  return [];
}
function isCall(f) { return !!(f && f.outcome); }   // activities de llamada tienen outcome; tareas/cambios de stage no

// ============================================================================
// ⚙️ FASE 1 — ACTIVITY CRM (WF9 v3)
//
// Entrada: eventos reclamados de wf_call_events (claim atómico con lease).
// Para cada evento decide UNA de estas salidas:
//   RECEIVED  -> todavía no es terminal (llamada/conversación en curso) o falta
//                enriquecer: se reintenta más tarde SIN tocar el CRM.
//   FAILED    -> error técnico: reintento con backoff. Nunca se marca hecho.
//   SKIPPED   -> no corresponde crear nada (enlazado a un job, Activity de
//                Asterisk que ya registró WF2, lead legado, etc.). Queda auditado.
//   DONE/STALE-> Activity creada/confirmada en LeadStudio (exactamente una).
//                El ciclo de vida lo aplica la Fase 2 y recién ahí el evento
//                queda finalizado.
//
// Reglas clave:
//  - Stringee: la unidad de llamada es el JOB (stringee:<job_id>). El estado del
//    worker (GET /calls/:job_id) es la verdad telefónica. La conversación de
//    ElevenLabs sólo clasifica un job CONTESTADO; nunca crea otra Activity.
//  - Asterisk CONTESTADA (ledger de WF2, dispatched_at): WF2 NO crea la Activity (LeadStudio
//    fija durationSeconds en el POST y no lo deja editar). WF9 crea la ÚNICA Activity al terminar
//    la llamada, con CDR.billsec (respaldo: duración de ElevenLabs) y el ciclo de vida final.
//    Asterisk SIN ledger (WF2 anterior): WF2 es dueño de la Activity. WF9 sólo (a) corrige el ciclo de
//    vida cuando WF2 marcó CONNECTED pero no hubo conversación real (buzón /
//    silencio), sin crear Activity, o (b) registra la llamada si WF2 no dejó
//    ninguna Activity para ella (hueco real).
//  - Idempotencia en el CRM: cada Activity lleva providerCallId y "Ref: <key>"
//    en notes; antes de crear se buscan en los followups del lead.
//  - Máximo 9 intentos: el 9º sin contacto => CLOSED + stage UNRESPONSIVE.
//  - Un evento viejo nunca pisa un estado más nuevo: crea la Activity histórica
//    que falte y NO toca status / stage / nextFollowUpAt.
// ============================================================================

const WAIT = {
  JOB_SETTLE_SEC: 30,             // margen tras finished_at (WF2 termina su PATCH ATTEMPTING en segundos)
  JOB_RECHECK_SEC: 180,           // reconciliación de jobs no terminales: cada 3 min
  CONV_RECHECK_SEC: 120,          // conversación ElevenLabs aún no terminal
  ENRICH_SEC: 45,                 // 1ª pasada de un evento ElevenLabs: sólo se enriquece
  ASTERISK_READY_SEC: 20 * 60,    // WF2 (lotes de 5, timeout 60 s) ya registró su Activity
  ASTERISK_MATCH_BEFORE_SEC: 120,
  ASTERISK_MATCH_AFTER_SEC: 20 * 60,
  ASTERISK_DEFER_SETTLE_SEC: 45,          // llamada contestada diferida por WF2: sólo se espera a que ElevenLabs/CDR se asienten tras colgar
  ASTERISK_DEFER_GIVEUP_SEC: 6 * 3600,    // sin conversación terminal tras 6 h: se registra igual (una Activity, sin conversación confirmada)
  CDR_TOL_START_S: 60,                    // la conversación EL empieza al marcar o al contestar (tolerancia)
  CDR_TOL_END_S: 90,                      // tolerancia entre el fin de la conversación EL y el fin del CDR
  CDR_UNALIGNED_TOL_S: 240,              // sin datos de la conversación: el CDR debe empezar a ±4 min del despacho
  CDR_LATE_SEC: 150,                      // CDR tardío (escritura en lotes): hasta 150 s tras colgar se espera antes de usar la duración de ElevenLabs
  CDR_AMBIGUITY_S: 15,                    // dos CDR igual de plausibles -> ambiguo -> se usa ElevenLabs
  STRINGEE_CONV_LINK_SEC: 45 * 60,       // conversación Stringee sin job: esperar a que un job la enlace
  STRINGEE_CONV_MAX_WAIT_SEC: 6 * 3600,
  WORKER_404_GIVEUP_SEC: 2 * 3600,
  CONV_404_GIVEUP_SEC: 2 * 3600,
  TIME_BUDGET_MS: 150000,         // no empezar eventos nuevos pasados 150 s (lease = 10 min)
  CONCURRENCY: 6                  // leads procesados en paralelo (mismo lead = secuencial)
};
const HISTORICAL_NOTE =
  'Historical call recovered during reconciliation. A newer lead status already exists, so this call does not change the current lead lifecycle.';
const SIP_TEXT = {
  403: 'Forbidden', 404: 'Not Found', 408: 'Request Timeout', 480: 'Temporarily Unavailable',
  484: 'Address Incomplete', 486: 'Busy Here', 487: 'Request Terminated', 488: 'Not Acceptable Here',
