const claim_sql = [
  'UPDATE wf_call_events SET state = \'PROCESSING\', claim_token = ' + T + ',',
  'lease_until = UTC_TIMESTAMP(3) + INTERVAL ' + LEASE_MIN + ' MINUTE, process_attempts = process_attempts + 1',
