  '(SELECT COUNT(*) FROM wf_call_events x WHERE x.lead_id = e.lead_id AND x.source = \'stringee\' AND x.state IN (\'RECEIVED\', \'PROCESSING\', \'FAILED\') AND x.event_key <> e.event_key) AS lead_unresolved_jobs,',
  '(SELECT GROUP_CONCAT(x.followup_id) FROM wf_call_events x WHERE x.lead_id = e.lead_id AND x.followup_id IS NOT NULL AND x.event_key <> e.event_key AND x.created_at > UTC_TIMESTAMP(3) - INTERVAL 14 DAY) AS lead_claimed_followups,',
  'CASE WHEN e.source = \'elevenlabs\' THEN (SELECT x.event_key FROM wf_call_events x WHERE x.source = \'stringee\' AND (x.conversation_id = e.external_id',
  'OR (e.provider = \'stringee\' AND e.lead_id IS NOT NULL AND x.lead_id = e.lead_id AND e.call_attempts IS NOT NULL AND x.call_attempts = e.call_attempts',
  'AND e.event_at IS NOT NULL AND ABS(TIMESTAMPDIFF(SECOND, COALESCE(x.event_at, x.dispatched_at, x.first_seen_at), e.event_at)) <= 1800)) LIMIT 1) ELSE NULL END AS linked_job_key',
