};
const HISTORICAL_NOTE =
  'Historical call recovered during reconciliation. A newer lead status already exists, so this call does not change the current lead lifecycle.';
const SIP_TEXT = {
  403: 'Forbidden', 404: 'Not Found', 408: 'Request Timeout', 480: 'Temporarily Unavailable',
  484: 'Address Incomplete', 486: 'Busy Here', 487: 'Request Terminated', 488: 'Not Acceptable Here',
  500: 'Server Internal Error', 502: 'Bad Gateway', 503: 'Service Unavailable', 600: 'Busy Everywhere',
  603: 'Decline'
};
const STATUS_TEXT = {
  NO_ANSWER: 'Call not answered.',
  UNAVAILABLE: 'Number temporarily unavailable.',
  BUSY: 'Line busy.',
  REJECTED: 'Call rejected by the recipient.',
  FAILED: 'Call failed at the telephone network.'
