    log: ''
  }, o);
}
function requeue(ev, delaySec, o) {
  return res(ev, Object.assign({ state: 'RECEIVED', next_attempt_ms: NOW + Math.max(15, delaySec) * 1000 }, o));
}
function fail(ev, msg, o) {
  const n = safeInt(ev.error_count) + 1;
  const delay = Math.min(1800, 60 * Math.pow(2, Math.min(n - 1, 5)));
  return res(ev, Object.assign({ state: 'FAILED', error: String(msg).slice(0, 900), next_attempt_ms: NOW + delay * 1000 }, o));
}
function skip(ev, resolution, o) {
  return res(ev, Object.assign({ state: 'SKIPPED', resolution }, o));
}
function ageSec(fromMs) { return fromMs ? (NOW - fromMs) / 1000 : 0; }

// ---------- clasificación ----------
function userTurns(transcript) {
  const turns = [];
  for (const t of Array.isArray(transcript) ? transcript : []) {
    if (!t || t.role !== 'user') continue;
    const msg = String(t.message || '').trim();
    if (msg.replace(/[\p{P}\p{S}\s]/gu, '').length >= 2) turns.push(msg);
  }
  return turns;
}
function englishOnly(s) {
  const txt = String(s || '').replace(/\s+/g, ' ').trim();
  if (!txt) return '';
  // si trae escrituras no latinas (p.ej. devanagari), no se copia al CRM
  if (/[^\u0000-ɏ -⁯]/.test(txt)) return '';
  return txt;
}
function parseCallbackMs(raw, fallbackMs) {
  const v = String(raw || '').trim();
  if (v) {
    const t = new Date(v).getTime();
    if (Number.isFinite(t) && t > NOW - 3600e3 && t < NOW + 60 * 86400e3) return t;
  }
  return fallbackMs;
}
// Clasifica una conversación ElevenLabs YA TERMINAL (done / failed)
function classifyConversation(d, endMs) {
  const meta = d.metadata || {};
  const analysis = d.analysis || {};
  const dur = Number(meta.call_duration_secs || 0);
  const summary = String(analysis.transcript_summary || '');
  const term = String(meta.termination_reason || '').toLowerCase();
  const evalTxt = String(analysis.call_successful || 'unknown').toLowerCase();
  const turns = userTurns(d.transcript);
  const humanTurns = turns.filter(m => !IVR_RE.test(m));
  const voicemail = term.includes('voicemail') || /voice ?mail/i.test(summary) || (turns.length > 0 && humanTurns.length === 0);
  const tooShort = dur > 0 && dur < 8 && evalTxt !== 'success'; // mismo criterio que usaba WF9
  const dc = analysis.data_collection_results || {};
  const cbFlag = String((dc.callback_requested && dc.callback_requested.value) || '').toLowerCase();
  const interest = String((dc.user_interest && dc.user_interest.value) || '').toLowerCase();
  const callbackRequested = ['true', 'yes'].includes(cbFlag) || interest === 'callback_requested';

  if (!voicemail && !tooShort && humanTurns.length >= 1) {
    const parts = ['Call answered. Customer conversation took place.'];
    let callbackAtMs = null;
    if (callbackRequested) {
      callbackAtMs = parseCallbackMs(dc.callback_date && dc.callback_date.value, endMs + 24 * 3600e3);
      parts.push('Customer requested a callback for ' + iso(callbackAtMs) + ' (UTC).');
    }
    const sum = englishOnly(summary).slice(0, 300);
    if (sum) parts.push('Summary: ' + sum);
    parts.push('AI objective evaluation: ' + (['success', 'failure'].includes(evalTxt) ? evalTxt : 'unknown') + '.');
    return {
      kind: 'CONTACTED', sub: callbackRequested ? 'CALLBACK_REQUESTED' : 'CONVERSATION',
      outcome: 'CONNECTED', callStatus: 'ANSWERED', durationSec: dur,
      note: parts.join(' '), callbackAtMs, recordingSynced: 0
    };
  }
  if (voicemail) {
    return { kind: 'UNSUCCESSFUL', sub: 'VOICEMAIL', outcome: 'NO_ANSWER', callStatus: 'NO_ANSWER', durationSec: dur,
      note: 'Call reached voicemail or an operator message. No customer conversation.', recordingSynced: dur > 0 ? 0 : 1 };
  }
  if (dur <= 0) {
    return { kind: 'UNSUCCESSFUL', sub: 'NO_ANSWER', outcome: 'NO_ANSWER', callStatus: 'NO_ANSWER', durationSec: 0,
      note: 'Call not answered. The AI conversation never started.', recordingSynced: 1 };
  }
  return { kind: 'UNSUCCESSFUL', sub: 'NO_INTERACTION', outcome: 'NO_ANSWER', callStatus: 'NO_ANSWER', durationSec: dur,
    note: 'Call connected but no customer conversation was detected.', recordingSynced: 0 };
}
function classifyTelephony(job) {
  const fs = String(job.final_status || 'FAILED').toUpperCase();
  const code = Number(job.sip_code);
  const hasCode = Number.isInteger(code) && code >= 100 && code <= 699;
  const rawReason = String(job.sip_reason || '').trim();
  const reason = (hasCode && SIP_TEXT[code]) || (/^[\x20-\x7E]{1,60}$/.test(rawReason) ? rawReason : '');
  const head = STATUS_TEXT[fs] || STATUS_TEXT.FAILED;
  const sip = hasCode ? ' SIP ' + code + (reason ? ' (' + reason + ').' : '.') : '';
  return {
    kind: 'UNSUCCESSFUL', sub: 'TELEPHONY_' + fs,
    outcome: 'NO_ANSWER', callStatus: fs === 'FAILED' ? 'FAILED' : 'NO_ANSWER', durationSec: 0,
    note: head + sip, recordingSynced: 1
  };
}
function telephonyEvidence(job) {
  const code = Number(job.sip_code);
  return (Number.isInteger(code) && code >= 100 && code <= 699) ||
    !!job.ringing_at || !!job.stringee_call_id || !!job.answered_at || job.answered === true;
}
function isJobTerminal(job) {
  return !!job.final_status && !!job.finished_at && (job.status === 'completed' || job.status === 'failed');
}
function detectProvider(d) {
  const dyn = (d.conversation_initiation_client_data && d.conversation_initiation_client_data.dynamic_variables) || {};
  if (String(dyn.provider || '').toUpperCase() === 'STRINGEE') return 'stringee';
  const phone = String(dyn.phone || '').trim();
  if (phone.startsWith('+')) return 'asterisk';          // WF2 Asterisk manda E.164
  if (/^\d{8,15}$/.test(phone)) return 'stringee';       // worker Stringee manda sólo dígitos
  return 'asterisk';
}

// ---------- CRM ----------
function claimedSet(ev, ctx) {
  const s = new Set(String(ev.lead_claimed_followups || '').split(',').map(x => x.trim()).filter(Boolean));
  for (const id of ctx.claimed) s.add(id);
  return s;
}
function findOurs(fus, refs, savedId) {
  if (savedId) {
    const f = fus.find(x => String(x.id) === String(savedId));
    return f || { id: String(savedId), _assumed: true, createdAt: null };
  }
  for (const f of fus) {
    const pc = String(f.providerCallId || '');
    const notes = String(f.notes || '');
    for (const r of refs) {
      if (r && (pc === r || notes.includes('Ref: ' + r))) return f;
    }
  }
  return null;
}
async function postFollowup(leadId, body) {
  const path = '/leads/' + leadId + '/followups';
  let r = await ls('POST', path, body);
  if (r.status === 400) {
    // si el backend rechaza un campo opcional, se reintenta sin él (nunca se pierde la Activity)
    const txt = JSON.stringify(r.body || {});
    const b2 = Object.assign({}, body);
    let changed = false;
    if (/providerCallId/i.test(txt) && 'providerCallId' in b2) { delete b2.providerCallId; changed = true; }
    if (/nextActionAt/i.test(txt) && b2.nextActionAt === null) { delete b2.nextActionAt; changed = true; }
    if (changed) {
      console.log('⚠️ POST followup 400 por campo opcional; reintento sin él:', txt.slice(0, 200));
      r = await ls('POST', path, b2);
    }
  }
  const fu = r.ok && r.body && (r.body.followUp || r.body.followup);
  if (!fu || !fu.id) return { ok: false, err: 'HTTP ' + r.status + ' ' + JSON.stringify(r.body || {}).slice(0, 300) };
  return { ok: true, id: String(fu.id) };
}
function buildNotes(x, lifeAttempt, plan, stale) {
  const parts = [];
  if (stale) parts.push(HISTORICAL_NOTE);
  parts.push(x.cls.note);
  parts.push(attemptText(lifeAttempt));
  if (!stale && x.cls.kind !== 'CONTACTED') parts.push(plan.text);
  parts.push('Provider: ' + (x.provider === 'stringee' ? 'Stringee' : 'Asterisk') + '.');
  if (x.extraNote) parts.push(x.extraNote);
  const ref = ' Ref: ' + x.refs[0];
  return parts.join(' ').slice(0, CFG.NOTE_MAX - ref.length) + ref;
}
function staleReasons(ev, lead, fus, ours, x, batchLatestMs) {
  const reasons = [];
  const status = String(lead.status || '').toUpperCase();
  const upd = ms(lead.updatedAt) || 0;
  const oursMs = ours ? (ms(ours.createdAt) || 0) : 0;
  const newer = fus.find(f => isCall(f) && (!ours || String(f.id) !== String(ours.id)) && (ms(f.createdAt) || 0) > x.callEndMs + 120e3);
  if (newer) reasons.push('newer_crm_call');
  const latest = Math.max(Number(ev.lead_latest_lifecycle_at_ms) || 0, batchLatestMs || 0);
  if (latest && latest > x.callStartMs + 1000) reasons.push('newer_lifecycle_event');
  // Mientras el evento está sin resolver nadie toca el lead (queda ATTEMPTING y el Mantenimiento
  // no lo libera). Si el lead cambió DESPUÉS de terminar esta llamada (y no por nuestro propio POST),
  // hubo un despacho o un estado más nuevo: esta llamada es histórica.
  if (upd > Math.max(x.callEndMs, oursMs) + 120e3) reasons.push(status === 'ATTEMPTING' ? 'relocked_by_newer_dispatch' : 'lead_updated_after_call');
  if (lead.doNotCall) reasons.push('do_not_call');
  if (status === 'CLOSED' || status === 'UNREACHABLE') reasons.push('status_' + status);
  if (status === 'CONTACTED' && x.cls.kind !== 'CONTACTED') reasons.push('newer_contact');
  return reasons;
}

// Crea (o confirma) la Activity de UNA llamada real y planifica su ciclo de vida.
async function applyCall(ev, x, ctx) {
  const baseFields = {
    lead_id: x.leadId, provider: x.provider, phone: x.phone || null,
    call_attempts: validAttempt(x.N), conversation_id: x.convId || null,
    stringee_call_id: x.stringeeCallId || null, event_at_ms: x.callStartMs
  };
  const lr = await ls('GET', '/leads/' + x.leadId);
  if (lr.status === 404) {
    if (ageSec(x.callEndMs) > 3600) return skip(ev, 'LEAD_NOT_FOUND', baseFields);
    return fail(ev, 'LeadStudio GET lead 404 (reintento)', baseFields);
  }
  if (!lr.ok) return fail(ev, 'LeadStudio GET lead HTTP ' + lr.status, baseFields);
  const lead = unwrapLead(lr.body);
  if (!lead) return fail(ev, 'LeadStudio GET lead: respuesta sin lead', baseFields);
  const fr = await ls('GET', '/leads/' + x.leadId + '/followups');
  if (!fr.ok) return fail(ev, 'LeadStudio GET followups HTTP ' + fr.status, baseFields);
  const fus = listFollowups(fr.body);

  const ours = findOurs(fus, x.refs, ev.followup_id);
  if (!ours && x.legacyWindow) {
    const taken = claimedSet(ev, ctx);
    const legacy = fus.find(f => isCall(f) && !taken.has(String(f.id)) &&
      (ms(f.createdAt) || 0) >= x.legacyWindow.from && (ms(f.createdAt) || 0) <= x.legacyWindow.to);
    if (legacy) {
      ctx.claimed.add(String(legacy.id));
      return skip(ev, 'ALREADY_IN_CRM', Object.assign({}, baseFields, { followup_id: String(legacy.id) }));
    }
  }
  if (!ours && ctx.leadsWritten.has(x.leadId)) {
    // un solo write por lead por corrida: el siguiente evento del mismo lead espera
    return requeue(ev, 20, Object.assign({}, baseFields, { resolution: 'WAITING_SAME_LEAD' }));
  }

  const A = safeInt(lead.attempts);
  const crmAttempt = ours ? (safeInt(ev.crm_attempt) || A) : A + 1;
  const lifeAttempt = Math.max(validAttempt(x.N) || 0, crmAttempt);
  const plan = x.cls.kind === 'CONTACTED' ? null : planFor(lifeAttempt, x.callStartMs);
  const target = x.cls.kind === 'CONTACTED'
    ? { status: 'CONTACTED', stage: null }
    : (plan.exhausted ? { status: 'CLOSED', stage: CFG.EXHAUSTED_STAGE } : { status: 'NO_ANSWER', stage: null });
  const leadStatus = String(lead.status || '').toUpperCase();
  const leadStage = String(lead.stage || '').toUpperCase();
  const atTarget = leadStatus === target.status && (!target.stage || leadStage === target.stage);
  const reasons = staleReasons(ev, lead, fus, ours, x, ctx.batchLatest.get(x.leadId));
  // Si ya creamos esta Activity antes y la Fase 2 quedó a medias (p.ej. status aplicado
  // pero stage no), el estado del lead lo puso ESTE evento: no es "más nuevo".
  const selfPartial = !!ours && !!ev.followup_id && leadStatus === target.status;
  const stale = reasons.length > 0 && !selfPartial;

  let followupId = ours ? String(ours.id) : null;
  let createdNow = false;
  if (!followupId) {
    const body = {
      type: 'CALL',
      outcome: x.cls.outcome,
      callStatus: x.cls.callStatus,
      durationSeconds: Math.max(0, Math.round(Number(x.cls.durationSec) || 0)),
      // evento histórico: la nota muestra el número de intento con el que se despachó la llamada
      notes: buildNotes(x, stale && validAttempt(x.N) ? validAttempt(x.N) : lifeAttempt, plan, stale),
      providerCallId: x.refs[0]
    };
    if (!stale) {
      if (x.cls.kind === 'CONTACTED') {
        if (x.cls.callbackAtMs) body.nextActionAt = iso(Math.max(x.cls.callbackAtMs, NOW + 60e3));
      } else if (!plan.exhausted) {
        // nextActionAt es el campo que LeadStudio usa para lead.nextFollowUpAt (R3)
        body.nextActionAt = iso(Math.max(plan.atMs, NOW + 60e3));
      } else {
        body.nextActionAt = null; // agotado: sin próximo contacto
      }
    }
    const pr = await postFollowup(x.leadId, body);
    if (!pr.ok) return fail(ev, 'POST followup falló: ' + pr.err, baseFields);
    followupId = pr.id;
    createdNow = true;
  }
  ctx.leadsWritten.add(x.leadId);
  ctx.claimed.add(followupId);

  let lifecycle = null;
  let lifecycleApplied = 0;
  if (!stale) {
    lifecycleApplied = 1;
    ctx.batchLatest.set(x.leadId, Math.max(ctx.batchLatest.get(x.leadId) || 0, x.callStartMs));
    if (!atTarget) {
      lifecycle = { status: target.status, stage: target.stage, from_status: leadStatus, from_stage: leadStage };
    }
  }
  const state = stale ? 'STALE' : 'DONE';
  let resolution;
  if (createdNow) resolution = stale ? 'HISTORICAL_ACTIVITY_CREATED' : (target.stage ? 'ACTIVITY_CREATED_EXHAUSTED' : 'ACTIVITY_CREATED');
  else resolution = stale ? 'HISTORICAL_ACTIVITY_PRESENT' : 'ACTIVITY_PRESENT';
  if (x.resolutionPrefix) resolution = x.resolutionPrefix + '_' + resolution;

  return res(ev, Object.assign({}, baseFields, {
    state,
    resolution: resolution.slice(0, 48),
    crm_attempt: crmAttempt,
    followup_id: followupId,
    created_now: createdNow,
    lifecycle,
    lifecycle_applied: lifecycleApplied,
    stale_reasons: reasons,
    fcf: {
      phone: String(x.phone || '').slice(0, 20),
      lead_id: x.leadId,
      followup_id: followupId,
      provider: x.provider,
      outcome: x.cls.outcome,
      call_status: x.cls.callStatus,
      recording_synced: x.cls.recordingSynced
    },
    log: `${x.provider} ${x.leadId} intento ${lifeAttempt} ${x.cls.kind}/${x.cls.sub} -> ${state}` +
      (lifecycle ? ` (${lifecycle.status}${lifecycle.stage ? '/' + lifecycle.stage : ''})` : '') +
      (reasons.length ? ' [' + reasons.join(',') + ']' : '')
  }));
}

// ---------- fuentes ----------
async function fetchConversation(convId) {
  return http('GET', CFG.EL_BASE + '/' + encodeURIComponent(convId), { headers: { 'xi-api-key': CFG.EL_KEY }, timeout: 20000 });
}

async function processStringeeJob(ev, ctx) {
  const jobId = String(ev.external_id || '');
  if (!UUID_RE.test(jobId)) return skip(ev, 'INVALID_JOB_ID');
  const firstSeen = Number(ev.dispatched_at_ms) || Number(ev.first_seen_at_ms) || NOW;
  const w = await http('GET', CFG.WORKER_BASE + '/calls/' + jobId, { timeout: 15000 });
  if (w.status === 404) {
    // el worker no conoce el job: NO se consume intento; se reintenta y, pasado el margen, se audita
    if (ageSec(firstSeen) > WAIT.WORKER_404_GIVEUP_SEC) {
      console.error('🚨 Job Stringee desconocido para el worker tras 2 h (sin Activity, sin intento):', jobId);
      return skip(ev, 'WORKER_JOB_NOT_FOUND');
    }
    return fail(ev, 'worker 404 call_not_found');
  }
  if (!w.ok) return fail(ev, 'worker HTTP ' + w.status + ' ' + JSON.stringify(w.body || {}).slice(0, 150));
  const job = w.body || {};
  if (String(job.job_id || '') !== jobId) return fail(ev, 'worker devolvió un job distinto');

  const leadId = String(job.lead_id || '').trim();
  const startMs = ms(job.started_at) || ms(job.created_at) || firstSeen;
  const convId = CONV_RE.test(String(job.elevenlabs_conversation_id || '')) ? job.elevenlabs_conversation_id : null;
  const base = {
    lead_id: UUID_RE.test(leadId) ? leadId : null, provider: 'stringee', phone: job.phone || ev.phone || null,
    call_attempts: validAttempt(job.call_attempts) || validAttempt(ev.call_attempts),
    conversation_id: convId, stringee_call_id: job.stringee_call_id || null, event_at_ms: startMs
  };

  if (!isJobTerminal(job)) {
    if (ageSec(ms(job.created_at) || firstSeen) > 3 * 3600) console.error('🚨 Job Stringee sin estado final hace >3 h:', jobId);
    return requeue(ev, WAIT.JOB_RECHECK_SEC, Object.assign({}, base, { resolution: 'WAITING_JOB_FINAL' }));
  }
  const endMs = ms(job.finished_at) || NOW;
  if (ageSec(endMs) < WAIT.JOB_SETTLE_SEC) return requeue(ev, WAIT.JOB_SETTLE_SEC, Object.assign({}, base, { resolution: 'WAITING_JOB_SETTLE' }));
  if (!UUID_RE.test(leadId)) return skip(ev, 'LEGACY_OR_INVALID_LEAD_ID', base);

  // Fallo del proveedor SIN evidencia telefónica: no es un intento real.
  // Sin Activity, sin consumir intento; el lead vuelve a NOT_CONTACTED. Queda auditado.
  if (String(job.final_status).toUpperCase() === 'FAILED' && !telephonyEvidence(job)) {
    const lr = await ls('GET', '/leads/' + leadId);
    if (!lr.ok) return fail(ev, 'LeadStudio GET lead HTTP ' + lr.status, base);
    const lead = unwrapLead(lr.body) || {};
    const st = String(lead.status || '').toUpperCase();
    const upd = ms(lead.updatedAt) || 0;
    const newer = Math.max(Number(ev.lead_latest_lifecycle_at_ms) || 0, ctx.batchLatest.get(leadId) || 0) > startMs + 1000;
    if (st === 'ATTEMPTING' && upd <= endMs + 120e3 && !newer) {
      return res(ev, Object.assign({}, base, {
        state: 'DONE', resolution: 'PROVIDER_FAILURE_RELEASED',
        lifecycle: { status: 'NOT_CONTACTED', stage: null, from_status: st, provider_failure: true },
        log: 'stringee ' + leadId + ' fallo de proveedor sin evidencia telefónica -> NOT_CONTACTED (no consume intento)'
      }));
    }
    return res(ev, Object.assign({}, base, { state: 'DONE', resolution: 'PROVIDER_FAILURE_NO_RELEASE',
      log: 'stringee ' + leadId + ' fallo de proveedor sin evidencia; lead en ' + st + ' (no se toca)' }));
  }

  let cls;
  let extraNote = null;
  if (job.answered === true) {
    if (convId) {
      const c = await fetchConversation(convId);
      if (c.status === 404) {
        if (ageSec(endMs) <= WAIT.CONV_404_GIVEUP_SEC) return fail(ev, 'ElevenLabs 404 para ' + convId + ' (reintento)', base);
        cls = { kind: 'UNSUCCESSFUL', sub: 'ANSWERED_CONVERSATION_MISSING', outcome: 'NO_ANSWER', callStatus: 'NO_ANSWER', durationSec: 0,
          note: 'Call answered but the AI conversation record is not available. No customer conversation could be confirmed.', recordingSynced: 0 };
      } else if (!c.ok) {
        return fail(ev, 'ElevenLabs HTTP ' + c.status, base);
      } else {
        const d = c.body || {};
        const status = String(d.status || '').toLowerCase();
        if (status !== 'done' && status !== 'failed') {
          if (ageSec(endMs) > 3 * 3600) console.error('🚨 Conversación sin estado terminal >3 h:', convId, status);
          return requeue(ev, WAIT.CONV_RECHECK_SEC, Object.assign({}, base, { resolution: 'WAITING_CONVERSATION' }));
        }
        cls = classifyConversation(d, endMs);
      }
    } else {
      // contestó pero el puente de IA no llegó a conectar: 1 Activity, ciclo 3x3
      const ansMs = ms(job.answered_at) || endMs;
      cls = { kind: 'UNSUCCESSFUL', sub: 'ANSWERED_NO_AI', outcome: 'NO_ANSWER', callStatus: 'NO_ANSWER',
        durationSec: Math.max(0, Math.round((endMs - ansMs) / 1000)),
        note: 'Call answered but the AI assistant could not connect (Stringee bridge). No customer conversation took place.', recordingSynced: 0 };
    }
  } else {
    cls = classifyTelephony(job);
    if (job.error === 'worker_restarted') extraNote = 'The dialer restarted during this call.';
  }
  return applyCall(ev, {
    provider: 'stringee', leadId, phone: String(job.phone || ev.phone || ''), N: job.call_attempts,
    refs: ['stringee:' + jobId].concat(convId ? ['elevenlabs:' + convId] : []),
    cls, callStartMs: startMs, callEndMs: endMs, convId, stringeeCallId: job.stringee_call_id || null, extraNote
  }, ctx);
}

async function processElevenLabs(ev, ctx) {
  const convId = String(ev.external_id || '');
  if (!CONV_RE.test(convId)) return skip(ev, 'INVALID_CONVERSATION_ID');
  if (ev.linked_job_key) return skip(ev, 'LINKED_TO_STRINGEE_JOB', { provider: 'stringee', conversation_id: convId, lead_id: ev.lead_id || null });
  // Asterisk ya enriquecido y todavía dentro de la espera de WF2: no hace falta llamar a ninguna API
  if (ev.provider === 'asterisk' && ev.lead_id && Number(ev.event_at_ms) > 0) {
    const readyAt0 = Number(ev.event_at_ms) + WAIT.ASTERISK_READY_SEC * 1000;
    if (NOW < readyAt0) return requeue(ev, (readyAt0 - NOW) / 1000, { resolution: 'WAITING_WF2_ACTIVITY', conversation_id: convId });
  }

  const c = await fetchConversation(convId);
  if (c.status === 404) {
    if (ageSec(Number(ev.first_seen_at_ms) || NOW) > WAIT.CONV_404_GIVEUP_SEC) return skip(ev, 'CONVERSATION_NOT_FOUND');
    return fail(ev, 'ElevenLabs 404 ' + convId);
  }
  if (!c.ok) return fail(ev, 'ElevenLabs HTTP ' + c.status);
  const d = c.body || {};
  const meta = d.metadata || {};
  const dyn = (d.conversation_initiation_client_data && d.conversation_initiation_client_data.dynamic_variables) || {};
  const startMs = (Number(meta.start_time_unix_secs) || 0) * 1000 || Number(ev.event_at_ms) || NOW;
  const dur = Number(meta.call_duration_secs || 0);
  const endMs = startMs + dur * 1000;
  const provider = detectProvider(d);
  const leadId = String(dyn.lead_id || '').trim();
  const phone = String(dyn.phone || '').replace(/[^0-9+]/g, '');
  const base = { provider, conversation_id: convId, event_at_ms: startMs, phone: phone || null,
    lead_id: UUID_RE.test(leadId) ? leadId : null, call_attempts: validAttempt(dyn.call_attempts) };

  const status = String(d.status || '').toLowerCase();
  if (status !== 'done' && status !== 'failed') {
    if (ageSec(startMs) > 3 * 3600) console.error('🚨 Conversación sin estado terminal >3 h:', convId, status);
    return requeue(ev, WAIT.CONV_RECHECK_SEC, Object.assign({}, base, { resolution: 'WAITING_CONVERSATION' }));
  }
  if (!UUID_RE.test(leadId)) return skip(ev, 'MISSING_OR_LEGACY_LEAD_ID', base);

  // 1ª pasada: guardar lead / proveedor / intento para que el claim pueda enlazar
  // esta conversación con su job Stringee o con las Activities ya tomadas.
  if (ev.lead_id !== leadId || ev.provider !== provider || (base.call_attempts && Number(ev.call_attempts) !== base.call_attempts)) {
    return requeue(ev, WAIT.ENRICH_SEC, Object.assign({}, base, { resolution: 'ENRICHED' }));
  }

  if (provider === 'stringee') {
    // La Activity de Stringee la crea el JOB. Esta conversación sólo espera a que un job la enlace.
    if (Number(ev.lead_unresolved_jobs) > 0 && ageSec(startMs) < WAIT.STRINGEE_CONV_MAX_WAIT_SEC) {
      return requeue(ev, 300, Object.assign({}, base, { resolution: 'WAITING_STRINGEE_JOB' }));
    }
    if (ageSec(startMs) < WAIT.STRINGEE_CONV_LINK_SEC) {
      return requeue(ev, WAIT.STRINGEE_CONV_LINK_SEC - ageSec(startMs), Object.assign({}, base, { resolution: 'WAITING_STRINGEE_JOB' }));
    }
    // Sin job en el ledger (dispatch anterior al despliegue o ledger fallido):
    // se registra UNA Activity desde la conversación. El puente sólo abre
    // ElevenLabs cuando el teléfono contestó (R2).
    const cls = classifyConversation(d, endMs);
    return applyCall(ev, {
      provider: 'stringee', leadId, phone, N: dyn.call_attempts, refs: ['elevenlabs:' + convId],
      cls, callStartMs: startMs, callEndMs: endMs, convId,
      legacyWindow: { from: startMs - 120e3, to: endMs + 30 * 60e3 }, resolutionPrefix: 'STRINGEE_FALLBACK'
    }, ctx);
  }

  // ---------------- Asterisk ----------------
  const readyAt = startMs + Math.max(WAIT.ASTERISK_READY_SEC, dur + 180) * 1000;
  if (NOW < readyAt) return requeue(ev, (readyAt - NOW) / 1000, Object.assign({}, base, { resolution: 'WAITING_WF2_ACTIVITY' }));

  const lr = await ls('GET', '/leads/' + leadId);
  if (lr.status === 404) {
    if (ageSec(endMs) > 3600) return skip(ev, 'LEAD_NOT_FOUND', base);
    return fail(ev, 'LeadStudio GET lead 404 (reintento)', base);
  }
  if (!lr.ok) return fail(ev, 'LeadStudio GET lead HTTP ' + lr.status, base);
  const lead = unwrapLead(lr.body);
  if (!lead) return fail(ev, 'LeadStudio GET lead: respuesta sin lead', base);
  const fr = await ls('GET', '/leads/' + leadId + '/followups');
  if (!fr.ok) return fail(ev, 'LeadStudio GET followups HTTP ' + fr.status, base);
  const fus = listFollowups(fr.body);
  const cls = classifyConversation(d, endMs);

  // ¿Ya registramos antes esta llamada como hueco (Activity propia con Ref)?
  const gapOurs = findOurs(fus, ['elevenlabs:' + convId], null);
  if (!gapOurs) {
    const taken = claimedSet(ev, ctx);
    const from = startMs - WAIT.ASTERISK_MATCH_BEFORE_SEC * 1000;
    const to = startMs + WAIT.ASTERISK_MATCH_AFTER_SEC * 1000;
    // 1) Activity de WF2 ya enlazada en una pasada anterior (corrección que falló y se reintenta)
    const saved = ev.followup_id ? fus.find(f => String(f.id) === String(ev.followup_id) && isCall(f)) : null;
    // 2) WF2 escribe el conversation_id en las notes de CONNECTED: match exacto
    const exact = fus.find(f => isCall(f) && String(f.notes || '').includes(convId));
    // 3) ventana de tiempo, excluyendo Activities ya tomadas por otros eventos del lead
    const inWin = fus.filter(f => isCall(f) && !taken.has(String(f.id)) && (ms(f.createdAt) || 0) >= from && (ms(f.createdAt) || 0) <= to);
    const matched = saved || exact || inWin.slice().sort((a, b) => (ms(a.createdAt) || 0) - (ms(b.createdAt) || 0))[0];
    if (matched) {
      ctx.claimed.add(String(matched.id));
      const matchedMs = ms(matched.createdAt) || startMs;
      if (String(matched.outcome).toUpperCase() === 'CONNECTED' && cls.kind !== 'CONTACTED') {
        // WF2 marcó CONNECTED pero no hubo conversación real (buzón / silencio / operador):
        // se corrige SÓLO el ciclo de vida, sin crear otra Activity.
        const st = String(lead.status || '').toUpperCase();
        const newerCall = fus.find(f => isCall(f) && String(f.id) !== String(matched.id) && (ms(f.createdAt) || 0) > matchedMs + 5000);
        const newerLife = Math.max(Number(ev.lead_latest_lifecycle_at_ms) || 0, ctx.batchLatest.get(leadId) || 0) > startMs + 1000;
        const updMs = ms(lead.updatedAt) || 0;
        // sólo si el lead sigue exactamente como lo dejó WF2 (nadie lo tocó después de su Activity)
        if (st === 'CONTACTED' && !newerCall && !newerLife && updMs <= matchedMs + 600e3 && !lead.doNotCall && !ctx.leadsWritten.has(leadId)) {
          ctx.leadsWritten.add(leadId);
          ctx.batchLatest.set(leadId, Math.max(ctx.batchLatest.get(leadId) || 0, startMs));
          const A = safeInt(lead.attempts); // WF2 ya contó esta llamada
          const plan = planFor(Math.max(A, validAttempt(dyn.call_attempts) || 0), startMs);
          const retryMs = plan.exhausted ? null : Math.max(plan.atMs, NOW + 60e3);
          return res(ev, Object.assign({}, base, {
            state: 'DONE',
            resolution: plan.exhausted ? 'ASTERISK_CORRECTED_EXHAUSTED' : 'ASTERISK_LIFECYCLE_CORRECTED',
            followup_id: String(matched.id),
            crm_attempt: A,
            lifecycle: plan.exhausted
              ? { status: 'CLOSED', stage: CFG.EXHAUSTED_STAGE, from_status: st }
              : { status: 'NO_ANSWER', stage: null, from_status: st },
            lifecycle_applied: 1,
            // LeadStudio no permite fijar nextFollowUpAt sin crear otra Activity (R3):
            // el próximo reintento queda retenido aquí y lo respeta el Mantenimiento de WF2.
            next_retry_ms: retryMs,
            log: 'asterisk ' + leadId + ' WF2=CONNECTED pero ' + cls.sub + ' -> ' +
              (plan.exhausted ? 'CLOSED/UNRESPONSIVE' : 'NO_ANSWER (reintento retenido ' + iso(retryMs) + ')')
          }));
        }
        return skip(ev, 'ASTERISK_CORRECTION_NOT_APPLICABLE', Object.assign({}, base, { followup_id: String(matched.id) }));
      }
      return skip(ev, 'ASTERISK_OWNED_BY_WF2', Object.assign({}, base, { followup_id: String(matched.id) }));
    }
  }
  // Hueco: WF2 no dejó ninguna Activity para esta llamada Asterisk (p.ej. timeout
  // del dial clasificado como error de proveedor). Se registra UNA.
  const evGap = Object.assign({}, ev, { followup_id: gapOurs ? String(gapOurs.id) : null });
  return applyCall(evGap, {
    provider: 'asterisk', leadId, phone, N: dyn.call_attempts, refs: ['elevenlabs:' + convId],
    cls, callStartMs: startMs, callEndMs: endMs, convId, resolutionPrefix: 'ASTERISK_GAP'
  }, ctx);
}

// ---------- SQL de wf_call_followups ----------
function fcfSql(r) {
  if (!r.fcf || !r.followup_id || !(r.state === 'DONE' || r.state === 'STALE')) {
    return 'SELECT 1 AS noop';
  }
  const f = r.fcf;
  return 'INSERT INTO wf_call_followups (phone, lead_id, followup_id, provider, outcome, call_status, recording_synced) ' +
    'SELECT ' + [q(f.phone || ''), q(f.lead_id), q(f.followup_id), q(f.provider), q(f.outcome), q(f.call_status), q(Number(f.recording_synced) ? 1 : 0)].join(', ') +
    ' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM wf_call_followups WHERE followup_id = ' + q(f.followup_id) + ')';
}

// ============================================================================
// MAIN
// ============================================================================
const START = Date.now();
const rows = $input.all().map(i => i.json || {});
const events = rows.filter(r => r && r.event_key && r.claim_token);
const bad = rows.filter(r => r && Object.keys(r).some(k => k !== 'success') && !(r.event_key && r.claim_token));
if (bad.length) console.error('🚨 Fase 1: filas sin event_key/claim_token (¿error MySQL?):', JSON.stringify(bad).slice(0, 300));

// agrupar por lead (mismo lead = secuencial y en orden cronológico; leads distintos = en paralelo)
const groups = new Map();
for (const ev of events) {
  const k = ev.lead_id ? 'lead:' + ev.lead_id : 'ev:' + ev.event_key;
  if (!groups.has(k)) groups.set(k, []);
  groups.get(k).push(ev);
}
for (const g of groups.values()) g.sort((a, b) => (Number(a.event_at_ms) || Number(a.first_seen_at_ms) || 0) - (Number(b.event_at_ms) || Number(b.first_seen_at_ms) || 0));

const ctx = { leadsWritten: new Set(), batchLatest: new Map(), claimed: new Set() };
const results = new Map();
async function runOne(ev) {
  let r;
  if (Date.now() - START > WAIT.TIME_BUDGET_MS) {
    r = requeue(ev, 15, { resolution: 'DEFERRED_TIME_BUDGET' });
  } else {
    try {
      if (ev.source === 'stringee') r = await processStringeeJob(ev, ctx);
      else if (ev.source === 'elevenlabs') r = await processElevenLabs(ev, ctx);
      else r = skip(ev, 'UNKNOWN_SOURCE');
    } catch (e) {
      r = fail(ev, 'excepción: ' + String((e && e.message) || e));
    }
  }
  r.fcf_sql = fcfSql(r);
  if (r.log) console.log('📞 ' + r.log);
  if (r.state === 'FAILED') console.error('❌ ' + r.event_key + ': ' + r.error);
  results.set(ev.event_key, r);
}
const queue = [...groups.values()];
async function worker() {
  while (queue.length) {
    const g = queue.shift();
    for (const ev of g) await runOne(ev);
  }
}
await Promise.all(Array.from({ length: Math.min(WAIT.CONCURRENCY, queue.length) }, worker));

const out = events.map(ev => ({ json: results.get(ev.event_key) }));
console.log(`⚙️ Fase 1: ${out.length} eventos | ` + ['DONE', 'STALE', 'SKIPPED', 'RECEIVED', 'FAILED'].map(s => s + '=' + out.filter(o => o.json.state === s).length).join(' '));
return out;

