const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const CONV_RE = /^conv_[A-Za-z0-9]{8,64}$/;

// HTTP que nunca lanza: devuelve {ok,status,body}
async function http(method, url, opts = {}) {
  try {
    const r = await self.helpers.httpRequest({
      method,
      url,
      body: opts.body,
      json: true,
      headers: Object.assign({ 'Content-Type': 'application/json' }, opts.headers || {}),
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
      timeout: opts.timeout || 20000
    });
    return { ok: r.statusCode >= 200 && r.statusCode < 300, status: r.statusCode, body: r.body };
  } catch (e) {
    return { ok: false, status: 0, body: { error: String((e && e.message) || e) } };
  }
}

let TOKEN = null;
async function getToken(force) {
  if (TOKEN && !force) return TOKEN;
  const r = await http('POST', CFG.TOKEN_URL, {});
  const t = r.ok && r.body && r.body.accessToken;
  if (!t) throw new Error('token service falló HTTP ' + r.status);
  TOKEN = t;
  return t;
}
async function ls(method, path, body) {
  let t = await getToken(false);
  let r = await http(method, CFG.LS_BASE + path, { body, headers: { Authorization: 'Bearer ' + t } });
  if (r.status === 401) {
    t = await getToken(true);
    r = await http(method, CFG.LS_BASE + path, { body, headers: { Authorization: 'Bearer ' + t } });
  }
  return r;
}

// Literales SQL seguros (MariaDB con escapes de backslash activos).
// El nodo MySQL de n8n elimina los saltos de línea al separar sentencias,
// por eso aquí nunca se dejan saltos de línea crudos dentro de un literal.
function q(v) {
  if (v === null || v === undefined) return 'NULL';
  if (typeof v === 'number') return Number.isFinite(v) ? String(Math.trunc(v)) : 'NULL';
  const s = String(v)
    .replace(/\u0000/g, '')
    .replace(/[\r\n]+/g, ' ').replace(/\$/g, '')
    .replace(/\\/g, '\\\\')
    .replace(/'/g, "''")
    .replace(/\{\{/g, '{ {')
    .replace(/\}\}/g, '} }');
  return "'" + s + "'";
}
// DATETIME(3) en UTC explícito
function dt(msv) {
  if (!msv || !Number.isFinite(Number(msv))) return 'NULL';
  return "'" + new Date(Number(msv)).toISOString().replace('T', ' ').replace('Z', '') + "'";
}
function ms(v) {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number') return Number.isFinite(v) ? v : null;
  const t = new Date(v).getTime();
  return Number.isFinite(t) ? t : null;
}
function iso(msv) { return new Date(msv).toISOString(); }
function safeInt(v) { const n = Number(v); return Number.isFinite(n) && n >= 0 ? Math.trunc(n) : 0; }
function validAttempt(v) {
  const n = Number(v);
  return Number.isInteger(n) && n >= 1 && n <= 99 ? n : null;
}

// Mismo cálculo que WF2 (Classify Dial Result Asterisk): días hábiles saltan sábado y domingo
function addHours(d, h) { return new Date(d.getTime() + h * 3600000); }
function addBusinessDays(d, days) {
  const r = new Date(d.getTime());
  let added = 0;
  while (added < days) {
    r.setDate(r.getDate() + 1);
    const wd = r.getDay();
    if (wd !== 0 && wd !== 6) added++;
  }
  return r;
}

// Política 3x3. attempt = número real de intento (1..9). >=9 => agotado.
function planFor(attempt, baseMs) {
  const a = Math.max(1, Math.trunc(attempt));
  if (a >= CFG.MAX_ATTEMPTS) {
    return { exhausted: true, text: 'Maximum of 9 call attempts reached. Lead closed as unresponsive.' };
  }
  const pos = ((a - 1) % 3) + 1;
  const cycle = Math.ceil(a / 3);
  const base = new Date(baseMs);
  let at, text;
  if (pos === 1) { at = addHours(base, 2); text = 'Next attempt in 2 hours.'; }
  else if (pos === 2) { at = addHours(base, 3); text = 'Next attempt in 3 hours.'; }
  else if (cycle === 1) { at = addBusinessDays(base, 2); text = 'End of cycle 1. Next cycle in 2 business days.'; }
  else { at = addBusinessDays(base, 3); text = 'End of cycle 2. Next cycle in 3 business days.'; }
  return { exhausted: false, atMs: at.getTime(), text, cycle, pos };
}
function attemptText(a) {
  if (a <= CFG.MAX_ATTEMPTS) {
    const pos = ((a - 1) % 3) + 1;
    const cycle = Math.ceil(a / 3);
    return 'Call attempt ' + a + ' of 9 (cycle ' + cycle + ', ' + pos + '/3).';
  }
  return 'Call attempt ' + a + ', beyond the configured maximum of 9.';
}

function unwrapLead(body) {
  if (!body || typeof body !== 'object') return null;
  if (body.lead && typeof body.lead === 'object') return body.lead;
  return body.id ? body : null;
}
function listFollowups(body) {
  if (Array.isArray(body)) return body;
  if (body && Array.isArray(body.followUps)) return body.followUps;
  if (body && Array.isArray(body.followups)) return body.followups;
  return [];
}
function isCall(f) { return !!(f && f.outcome); }   // activities de llamada tienen outcome; tareas/cambios de stage no

// ============================================================================
// ⚙️ FASE 2 — CICLO DE VIDA + CIERRE DEL EVENTO (WF9 v3)
//
// Corre DESPUÉS de que la Activity quedó creada en LeadStudio (Fase 1) y de que
// su followup_id quedó guardado en wf_call_followups.
//  - Aplica status (y stage UNRESPONSIVE en el intento 9) con PATCH separados,
//    igual que WF2: primero status, después stage.
//  - Si un PATCH falla, el evento queda FAILED (reintento con backoff) y conserva
//    el followup_id: el reintento NO crea otra Activity.
//  - Genera el UPDATE final de wf_call_events, protegido por claim_token.
// ============================================================================

const P1 = $('⚙️ Fase 1 — Activity CRM').all().map(i => i.json || {}).filter(r => r.event_key && r.claim_token);

async function patchLead(leadId, body) {
  let r = await ls('PATCH', '/leads/' + leadId, body);
  if (!r.ok && r.status === 400 && 'nextFollowUpAt' in body) {
    // si el backend no acepta nextFollowUpAt=null, el status se aplica igual sin ese campo
    const b2 = Object.assign({}, body); delete b2.nextFollowUpAt;
    r = await ls('PATCH', '/leads/' + leadId, b2);
  }
  if (!r.ok && r.status !== 400 && r.status !== 404) r = await ls('PATCH', '/leads/' + leadId, body); // 1 reintento inmediato
  return r;
}

function finalizeSql(r) {
  const finalStates = ['DONE', 'STALE', 'SKIPPED'];
  const isFinal = finalStates.includes(r.state);
  const sets = [
    'state = ' + q(r.state),
    'resolution = ' + q(r.resolution ? String(r.resolution).slice(0, 48) : null),
    'lead_id = COALESCE(' + q(r.lead_id) + ', lead_id)',
    'provider = COALESCE(' + q(r.provider) + ', provider)',
    'phone = COALESCE(' + q(r.phone ? String(r.phone).slice(0, 32) : null) + ', phone)',
    'call_attempts = COALESCE(' + q(validAttempt(r.call_attempts)) + ', call_attempts)',
    'crm_attempt = COALESCE(' + q(r.crm_attempt ? safeInt(r.crm_attempt) : null) + ', crm_attempt)',
    'event_at = COALESCE(' + dt(r.event_at_ms) + ', event_at)',
    'conversation_id = COALESCE(' + q(r.conversation_id) + ', conversation_id)',
    'stringee_call_id = COALESCE(' + q(r.stringee_call_id ? String(r.stringee_call_id).slice(0, 128) : null) + ', stringee_call_id)',
    'followup_id = COALESCE(' + q(r.followup_id) + ', followup_id)',
    'lifecycle_applied = GREATEST(lifecycle_applied, ' + (r.lifecycle_applied ? 1 : 0) + ')',
    'claim_token = NULL',
    'lease_until = NULL'
  ];
  if (r.state === 'DONE' && r.lifecycle_applied) sets.push('next_retry_at = ' + dt(r.next_retry_ms));
  if (!isFinal) sets.push('next_attempt_at = ' + dt(r.next_attempt_ms || (NOW + 60000)));
  if (r.state === 'FAILED') {
    sets.push('error_count = error_count + 1');
    sets.push('last_error = ' + q(String(r.error || 'error').slice(0, 1000)));
  }
  if (isFinal) sets.push('processed_at = UTC_TIMESTAMP(3)');
  return 'UPDATE wf_call_events SET ' + sets.join(', ') +
    ' WHERE event_key = ' + q(r.event_key) + ' AND claim_token = ' + q(r.claim_token);
}

const out = [];
let patched = 0, patchFail = 0;
for (const r0 of P1) {
  const r = Object.assign({}, r0);
  if (r.state === 'DONE' && r.lifecycle && r.lead_id) {
    const L = r.lifecycle;
    const body = { status: L.status };
    if (L.status === 'CLOSED') body.nextFollowUpAt = null;
    const s1 = await patchLead(r.lead_id, body);
    if (!s1.ok) {
      patchFail++;
      r.state = 'FAILED';
      r.lifecycle_applied = 0;
      r.error = 'PATCH status ' + L.status + ' HTTP ' + s1.status + ' ' + JSON.stringify(s1.body || {}).slice(0, 200);
      const n = safeInt(r.error_count) + 1;
      r.next_attempt_ms = NOW + Math.min(1800, 60 * Math.pow(2, Math.min(n - 1, 5))) * 1000;
    } else if (L.stage) {
      const s2 = await patchLead(r.lead_id, { stage: L.stage });
      if (!s2.ok) {
        // el status CLOSED ya quedó aplicado (no hay riesgo de otra llamada); se reintenta el stage
        patchFail++;
        r.state = 'FAILED';
        r.lifecycle_applied = 0;
        r.error = 'PATCH stage ' + L.stage + ' HTTP ' + s2.status + ' ' + JSON.stringify(s2.body || {}).slice(0, 200);
        const n = safeInt(r.error_count) + 1;
        r.next_attempt_ms = NOW + Math.min(1800, 60 * Math.pow(2, Math.min(n - 1, 5))) * 1000;
      } else {
        patched++;
      }
    } else {
      patched++;
    }
    if (r.state === 'DONE') {
      r.lifecycle_applied = 1;
      console.log('🏁 ' + r.lead_id + ' -> ' + L.status + (L.stage ? ' / ' + L.stage : '') + ' (' + r.resolution + ')');
    } else {
      console.error('❌ ' + r.event_key + ': ' + r.error + ' — la Activity ' + (r.followup_id || '-') + ' ya existe; se reintenta sólo el ciclo de vida');
    }
  }
  out.push({ json: {
    event_key: r.event_key,
    state: r.state,
    resolution: r.resolution,
    lead_id: r.lead_id,
    followup_id: r.followup_id,
    created_now: !!r.created_now,
    lifecycle: r.lifecycle ? (r.lifecycle.status + (r.lifecycle.stage ? '/' + r.lifecycle.stage : '')) : null,
    error: r.state === 'FAILED' ? r.error : null,
    sql: finalizeSql(r)
  } });
}
console.log(`⚙️ Fase 2: ${out.length} eventos | ciclo de vida aplicado=${patched} | PATCH fallidos=${patchFail}`);
return out;

const item = $input.first();
const raw = item.json;

// ── 1. Retrieve the RAW body if the webhook has "Raw Body" enabled ──────
// (needed to reliably verify the HMAC signature)
let rawStr = '';
try {
  if (item.binary && item.binary.data && item.binary.data.data) {
    rawStr = Buffer.from(item.binary.data.data, 'base64').toString('utf8');
  }
} catch (e) { /* no rawBody, continue with the parsed body */ }

let body = raw.body || raw;
if (rawStr) { try { body = JSON.parse(rawStr); } catch (e) {} }

// ── 2. HMAC verification (ElevenLabs format: t=timestamp,v0=signature) ─────────
let crypto = null;
try { crypto = require('crypto'); } catch (e) { console.warn('⚠️ El módulo crypto no está permitido en este n8n: la firma HMAC no se puede verificar (se procesa igual, como antes con firma inválida).'); }
const secret = 'wsec_98c0a66b3f1df7af8eaf22503381cb78ce648dc63da8eead8ce3dafc7a95b630';
const headers = raw.headers || {};
const sigHeader = String(headers['elevenlabs-signature'] || headers['ElevenLabs-Signature'] || '');
if (sigHeader) {
  const parts = Object.fromEntries(sigHeader.split(',').map(p => p.split('=')));
  const timestamp = parts['t'] || '';
  const receivedSig = parts['v0'] || parts['v1'] || '';
  if (timestamp && Math.abs(Date.now() / 1000 - Number(timestamp)) > 1800) {
    throw new Error('Webhook timestamp too old (>30min) — possible replay');
  }
  if (crypto && rawStr && receivedSig) {
    const expected = crypto.createHmac('sha256', secret).update(timestamp + '.' + rawStr).digest('hex');
    if (receivedSig !== expected) {
      console.warn('⚠️ HMAC mismatch — processing anyway. expected=' + expected + ' received=' + receivedSig + ' rawLen=' + rawStr.length);
    }
  } else if (receivedSig) {
    console.warn('⚠️ HMAC not verifiable without Raw Body — processing anyway. Enable "Raw Body" in the Webhook node.');
  }
}

const d = body.data || body;

const conversationId = String(d.conversation_id || d.conversationId || '');
const callSuccessful = String(d.analysis?.call_successful || d.call_successful || '').toLowerCase();
const summary        = d.analysis?.transcript_summary || d.summary || d.conversation_summary || '';
const durationSecs   = Number(d.metadata?.call_duration_secs || d.duration_secs || 0);
const callEndedBy    = String(d.metadata?.termination_reason || d.call_ended_by || '').toLowerCase();

let transcript = '';
if (Array.isArray(d.transcript)) {
  transcript = d.transcript.map(t => `${t.role === 'agent' ? '🤖' : '👤'} ${t.message || ''}`).join(' | ');
} else {
  transcript = typeof d.transcript === 'string' ? d.transcript : JSON.stringify(d.transcript || '');
}

const dc = d.analysis?.data_collection_results
        || d.analysis?.data_collection
        || d.data_collection_results
        || d.data_collection
        || {};

const interested    = String(dc.user_interest?.value      || '').toLowerCase();
const fullName      = String(dc.full_name?.value           || '').replace(/^=/, '').trim();
const callbackReq   = String(dc.callback_requested?.value  || '').toLowerCase();
const callbackDate  = String(dc.callback_date?.value       || '');
const accountOpened = String(dc.account_requested?.value   || '').toLowerCase();

const dynVars = d.conversation_initiation_client_data?.dynamic_variables
             || d.metadata?.dynamic_variables
             || body.conversation_initiation_client_data?.dynamic_variables
             || {};
const leadId = String(dynVars.lead_id || d.lead_id || body.lead_id || '');
const phone  = String(dynVars.phone   || d.phone   || '').replace(/[^0-9+]/g, '');

function canonicalCountry(rawCountry, rawPhone='') {
  const c = String(rawCountry || '').trim().toLowerCase();
  if (['india','in'].includes(c)) return 'india';
  if (['nepal','np'].includes(c)) return 'nepal';
  if (['slot3'].includes(c)) return 'slot3';
  if (['slot4'].includes(c)) return 'slot4';
  const p = String(rawPhone || '').replace(/[^0-9+]/g,'');
  if (p.startsWith('+977') || p.startsWith('977')) return 'nepal';
  if (p.startsWith('+91') || p.startsWith('91')) return 'india';
  return '';
}
const country = canonicalCountry(dynVars.country || d.country || body.country, phone);
const sourceSheet = String(
  dynVars._source_sheet ||
  ({india:'leads',nepal:'leads nepal',slot3:'leads slot3',slot4:'leads slot4'})[country] ||
  ''
);

const callAttempts = dynVars.call_attempts !== undefined ? Number(dynVars.call_attempts) : undefined;

const isVoicemail =
  callEndedBy.includes('voicemail') ||
  String(summary).toLowerCase().includes('voicemail') ||
  (durationSecs > 0 && durationSecs < 8 && callSuccessful !== 'success');

let status, last_call_status, notes;

if (!conversationId) {
  status = 'FAILED'; last_call_status = 'NO_CONV_ID';
  notes = 'Webhook without conversation_id';
} else if (durationSecs === 0) {
  status = 'NO_ANSWER'; last_call_status = 'NO_ANSWER';
  notes = 'No answer (0s duration) | ended: ' + callEndedBy;
} else if (callSuccessful === 'failure' || callSuccessful === 'failed') {
  status = 'FAILED'; last_call_status = 'FAILED';
  notes = 'Call failed: ' + (callEndedBy || 'no reason given');
} else if (isVoicemail) {
  status = 'VOICEMAIL'; last_call_status = 'VOICEMAIL';
  notes = '📵 Voicemail | duration: ' + durationSecs + 's';
} else if (callbackReq === 'true' || callbackReq === 'yes') {
  status = 'SCHEDULED'; last_call_status = 'CALLBACK_REQUESTED';
  notes = '📅 Requested callback | ' + String(summary).slice(0, 200);
} else {
  status = 'SUCCESSFUL'; last_call_status = 'COMPLETED';
  notes = 'Answered, full conversation | ' + String(summary).slice(0, 200);
}

console.log('📞 Post-call | lead:', leadId, '| status:', status, '| dur:', durationSecs + 's', '| conv:', conversationId);

const out = {
  lead_id:              leadId,
  country,
  _source_country: country,
  _source_sheet: sourceSheet,
  phone,
  status,
  last_call_status,
  notes,
  elevenlabs_call_id:   conversationId,
  conversation_summary: String(summary).slice(0, 500),
  full_name:            fullName || null,
  interested:           (interested === 'interested' || interested === 'true' || interested === 'yes') ? 'TRUE' : '',
  callback_requested:   (callbackReq === 'true' || callbackReq === 'yes') ? 'TRUE' : '',
  callback_date:        callbackDate,
  account_opened:       (accountOpened === 'yes' || accountOpened === 'true') ? 'PENDING' : '',
  duration_secs:        durationSecs,
  transcript:           transcript.slice(0, 1000),
  last_call_time:       new Date().toISOString()
};
if (callAttempts !== undefined && !Number.isNaN(callAttempts)) out.call_attempts = callAttempts;
if (!out.full_name) delete out.full_name;
if (!out.callback_date) delete out.callback_date;

// ── 3. WF9 v3: inbox durable (wf_call_events) ─────────────────────────────
// Este webhook YA NO crea Activities ni cambia el lead. Sólo registra
// "la conversación X terminó" en el inbox; el procesador (cada 1 min) la
// clasifica leyendo la conversación completa desde la API de ElevenLabs.
// Si este INSERT fallara, el polling (cada 3 min, ventana 60 min) la ingresa igual.
{
  const qv = v => {
    if (v === null || v === undefined || v === '') return 'NULL';
    if (typeof v === 'number') return Number.isFinite(v) ? String(Math.trunc(v)) : 'NULL';
    return "'" + String(v).replace(/\u0000/g, '').replace(/[\r\n]+/g, ' ').replace(/\$/g, '').replace(/\\/g, '\\\\').replace(/'/g, "''")
      .replace(/\{\{/g, '{ {').replace(/\}\}/g, '} }') + "'";
  };
  const convOk = /^conv_[A-Za-z0-9]{8,64}$/.test(conversationId);
  const provRaw = String(dynVars.provider || '').toUpperCase();
  const provider = provRaw === 'STRINGEE' ? 'stringee'
    : (phone.startsWith('+') ? 'asterisk' : (/^\d{8,15}$/.test(phone) ? 'stringee' : null));
  const startSecs = Number(d.metadata?.start_time_unix_secs || 0);
  const eventAt = startSecs > 0 ? "'" + new Date(startSecs * 1000).toISOString().replace('T', ' ').replace('Z', '') + "'" : 'NULL';
  const att = Number(dynVars.call_attempts);
  const attOk = Number.isInteger(att) && att >= 1 && att <= 99 ? att : null;
  const payload = JSON.stringify({ via: 'webhook', type: body.type || null, received_at: new Date().toISOString(), status: d.status || null });
  out.inbox_sql = !convOk ? 'SELECT 1 AS ignored' :
    'INSERT INTO wf_call_events (event_key, source, provider, external_id, lead_id, phone, call_attempts, event_at, ' +
    'first_seen_at, state, next_attempt_at, payload) VALUES (' +
    [qv('elevenlabs:' + conversationId), qv('elevenlabs'), qv(provider), qv(conversationId), qv(leadId.slice(0, 64)),
      qv(phone.slice(0, 32)), qv(attOk), eventAt, 'UTC_TIMESTAMP(3)', qv('RECEIVED'),
      'UTC_TIMESTAMP(3) + INTERVAL 60 SECOND', qv(payload)].join(', ') +
    ') ON DUPLICATE KEY UPDATE provider = COALESCE(provider, VALUES(provider)), lead_id = COALESCE(lead_id, VALUES(lead_id)), ' +
    'phone = COALESCE(phone, VALUES(phone)), call_attempts = COALESCE(call_attempts, VALUES(call_attempts)), ' +
    'event_at = COALESCE(event_at, VALUES(event_at)), ' +
    "next_attempt_at = IF(state = 'RECEIVED' AND (resolution IS NULL OR resolution = 'WAITING_CONVERSATION'), " +
    'LEAST(next_attempt_at, VALUES(next_attempt_at)), next_attempt_at)';
  if (!convOk) console.warn('⚠️ Post-call sin conversation_id válido: no se registra en el inbox');
}

return [{ json: out }];

// Vincular conversation_id de ElevenLabs a stringee_calls (solo Stringee = bare digits)
const d = $input.first().json;

// Stringee usa bare digits (sin +), Asterisk usa E.164 (con +)
const isStringee = d.phone && !String(d.phone).startsWith('+');

if (d.country !== 'india' || !isStringee || !d.elevenlabs_call_id) {
  return [{ json: { skip: true, reason: 'no es Stringee o no aplica (country=' + d.country + ', phone_format=' + (String(d.phone).startsWith('+') ? 'E164' : 'bare') + ')' } }];
}

const phoneDigits = String(d.phone).replace(/[^0-9]/g, '');
const last10 = phoneDigits.slice(-10);
const convId = String(d.elevenlabs_call_id).replace(/'/g, "''");

const sql = `UPDATE stringee_calls
  SET conversation_id = '${convId}'
  WHERE RIGHT(phone,10) = '${last10}'
    AND conversation_id IS NULL
    AND answered = 1
  ORDER BY start_time DESC
  LIMIT 1;`;

console.log('🔗 Stringee Conv-ID SQL (webhook):', sql.slice(0, 150));
return [{ json: { sql, phone: d.phone, last10, convId, provider: 'stringee' } }];

const KEY = 'sk_79048a9776812db4416e5c690d0c047132d565fee7d43acd';

const AGENT_IDS = [
  'agent_5701kramx550e3qs2tm11661b48p',
  'agent_7601m209ntj3fyrbg0dcq6w507yq'
];

// WF9 v3: ventana de reconciliación de 60 min (polling cada 3 min).
const WINDOW_MIN = 60;
// El detalle completo sólo se trae para los últimos 20 min (mismo alcance que antes: lo usa
// la rama de enlace conv-id de Stringee). El procesador del inbox lee el detalle por su cuenta.
const DETAIL_WINDOW_MIN = 20;
const after = Math.floor(Date.now()/1000) - (WINDOW_MIN * 60);
const H = { 'xi-api-key': KEY };
const base = 'https://api.elevenlabs.io/v1/convai/conversations';
const byId = new Map();

for (const agentId of [...new Set(AGENT_IDS.filter(Boolean))]) {
  let cursor = '';
  let page = 0;
  do {
    let url = `${base}?page_size=100&summary_mode=include&call_start_after_unix=${after}&agent_id=${encodeURIComponent(agentId)}`;
    if (cursor) url += `&cursor=${encodeURIComponent(cursor)}`;
    const res = await this.helpers.httpRequest({ method: 'GET', url, headers: H, json: true, timeout: 30000 });
    const convos = res.conversations || [];
    for (const c of convos) { if (c.conversation_id) byId.set(c.conversation_id, c); }
    cursor = res.has_more ? (res.next_cursor || '') : '';
    page++;
    console.log(`📄 ${agentId} page ${page}: +${convos.length} | unique ${byId.size}`);
  } while (cursor && page < 30);
}

const todas = [...byId.values()];
if (!todas.length) { console.log(`⚠️ No conversations in the last ${WINDOW_MIN} min`); return []; }

const detailAfter = Math.floor(Date.now()/1000) - (DETAIL_WINDOW_MIN * 60);
const recientes = todas.filter(c => Number(c.start_time_unix_secs || 0) >= detailAfter);
const CONCURRENCY = 10;
const out = [];
// conversaciones más viejas: sólo datos de la lista (el inbox las registra igual)
for (const c of todas) { if (Number(c.start_time_unix_secs || 0) < detailAfter) out.push({ json: { conversation_id: c.conversation_id, status: c.status, _lista: c, _detail: false } }); }
for (let i = 0; i < recientes.length; i += CONCURRENCY) {
  const chunk = recientes.slice(i, i + CONCURRENCY);
  const results = await Promise.allSettled(
    chunk.map(c => this.helpers.httpRequest({ method: 'GET', url: `${base}/${c.conversation_id}`, headers: H, json: true, timeout: 20000 }).then(det => ({ json: { ...det, _lista: c } })))
  );
  for (let j = 0; j < results.length; j++) {
    if (results[j].status === 'fulfilled') out.push(results[j].value);
    else { console.warn('⚠️ Failed to fetch detail ' + chunk[j].conversation_id + ': ' + results[j].reason?.message); out.push({ json: { conversation_id: chunk[j].conversation_id, status: chunk[j].status, _lista: chunk[j], _detail: false } }); }
  }
}
console.log(`✅ ${todas.length} conversaciones en ${WINDOW_MIN} min | detalle traído para ${recientes.length} (últimos ${DETAIL_WINDOW_MIN} min)`);
return out;

// Vincula conversation_id a stringee_calls — consume RAW de ElevenLabs (sin filtro de lead_id)
// Esto es independiente del filtro de Sheet (que descarta calls sin lead_id/sourceSheet)
const convos = $input.all().map(i => i.json);
const results = [];

for (const c of convos) {
  const d = c.data || c;

  const convId = String(d.conversation_id || '');
  if (!convId) continue;

  const dyn = d.conversation_initiation_client_data?.dynamic_variables || {};
  const phone = String(dyn.phone || '').replace(/[^0-9+]/g, '');
  let country = String(dyn.country || '').trim().toLowerCase();
  if (['in'].includes(country)) country = 'india';
  if (['np'].includes(country)) country = 'nepal';
  if (!country) {
    if (phone.startsWith('+977') || phone.startsWith('977')) country = 'nepal';
    else if (phone.startsWith('+91') || phone.startsWith('91')) country = 'india';
  }

  // Stringee = bare digits (sin +), Asterisk = E.164 (con +)
  const isStringee = phone && !phone.startsWith('+');

  if (country !== 'india' || !isStringee || !phone) continue;

  const phoneDigits = phone.replace(/[^0-9]/g, '');
  const last10 = phoneDigits.slice(-10);
  const convIdEscaped = convId.replace(/'/g, "''");

  const sql = `UPDATE stringee_calls
    SET conversation_id = '${convIdEscaped}'
    WHERE RIGHT(phone,10) = '${last10}'
      AND conversation_id IS NULL
      AND answered = 1
    ORDER BY start_time DESC
    LIMIT 1;`;

  results.push({ json: { sql, phone, last10, convId, provider: 'stringee' } });
}

if (results.length) console.log(`🔗 Stringee Conv-ID SQL (polling): ${results.length} filas a vincular`);
return results.length ? results : [{ json: { skip: true, reason: 'ninguna conversación raw es Stringee sin vincular' } }];

